@-moz-document url("chrome://") {

/* =====================================================
   Tidy Popup v2 - A clean theme for Zen Browser
   Making popup panels compact and modern
   ===================================================== */

/* -----------------------------------------------------
   CSS Custom Properties & Default Values
   These are overridden by user preferences
   ----------------------------------------------------- */
:root {
  /* Transition control (enabled/disabled via checkbox) */
  --tidy-transition-props: none;
}

/* Enable transitions when checkbox is true */
@media (-moz-pref("mod.tidypopupv2.enabletransitions")) {
  :root {
    --tidy-transition-props: background-color var(
      --mod-tidypopupv2-transitionduration,
      0.15s
    ) var(--mod-tidypopupv2-transitiontiming, ease) !important;
  }
}

/* Base values with preference overrides */
:root {
  /* Size preference (spacing) */
  --tidy-popup-padding: var(
    --mod-tidypopupv2-popupsize,
    6px
  ) !important;

  /* Border radius preferences */
  --tidy-radius: var(
    --mod-tidypopupv2-borderradius,
    8px
  ) !important;

  --tidy-button-radius: var(
    --mod-tidypopupv2-buttonradius,
    8px
  ) !important;

  /* Shadow customization */
  --tidy-popup-shadow: var(
    --mod-tidypopupv2-shadow,
    var(--panel-shadow)
  ) !important;

  --tidy-popup-shadow-margin: var(
    --mod-tidypopupv2-shadowmargin,
    var(--panel-shadow-margin)
  ) !important;

  /* Hover colors */
  --tidy-hover-light: rgba(80, 80, 250, 0.75);
  --tidy-hover-dark: rgba(80, 80, 250, 0.75);
}

/* -----------------------------------------------------
   Preference: Use Zen Browser primary color
   ----------------------------------------------------- */
@media (-moz-pref("mod.tidypopupv2.usezenprimarycolor")) {
  :root {
    --tidy-hover-light: var(--zen-primary-color);
    --tidy-hover-dark: var(--zen-primary-color);
  }
}

/* If not using Zen primary, use custom color preferences */
@media not (-moz-pref("mod.tidypopupv2.usezenprimarycolor")) {
  :root {
    --tidy-hover-light: var(
      --mod-tidypopupv2-hovercolor-light,
      rgba(80, 80, 250, 0.75)
    );
    --tidy-hover-dark: var(
      --mod-tidypopupv2-hovercolor-dark,
      rgba(80, 80, 250, 0.75)
    );
  }
}

