   Mode: Compact / Extended
   Controls density of popup layouts
   ----------------------------------------------------- */
/* Compact mode (default) */
@media (-moz-pref("mod.tidypopupv2.layoutmode", "compact")) {
  :root {
    --tidy-mode-padding: var(
      --mod-tidypopupv2-compactpadding,
      4px 8px
    ) !important;
    --tidy-mode-margin: var(
      --mod-tidypopupv2-compactmargin,
      var(--arrowpanel-menuitem-margin)
    ) !important;
  }
}

/* Extended mode */
@media (-moz-pref("mod.tidypopupv2.layoutmode", "extended")) {
  :root {
    --tidy-mode-padding: var(
      --mod-tidypopupv2-extendedpadding,
      8px 16px
    ) !important;
    --tidy-mode-margin: var(
      --mod-tidypopupv2-extendedmargin,
      4px
    ) !important;
  }
}

